+    pub fn parse(contents: &str) -> Result<Self> {
+        let Some(after_opening) = contents.strip_prefix("---\n") else {
+            bail!("template must start with YAML frontmatter");
+        };
+        let Some((frontmatter, preamble)) = after_opening.split_once("\n---\n") else {
+            bail!("template YAML frontmatter must end with ---");
+        };
+        let frontmatter: Frontmatter =
+            serde_yaml::from_str(frontmatter).context("failed to parse template frontmatter")?;
+
+        Ok(Self {
+            model: frontmatter.model,
+            preamble: preamble.trim().to_owned(),
+        })
+    }
